-- Completa a avaliação formal com cobertura rastreável das 14 seções e dos anexos A–F do POP.
UPDATE "training_assessments" AS a
SET "version" = a."version" + 1,
    "description" = 'Avaliação integral do POP-COM-01: cobre as 14 seções e os anexos visuais A–F, com aplicação em cenários de atendimento.',
    "updated_at" = now()
FROM "training_subjects" AS s
WHERE a."subject_id" = s."id"
  AND s."slug" = 'closer'
  AND a."id" = (
    SELECT min(initial."id")
    FROM "training_assessments" AS initial
    WHERE initial."subject_id" = s."id"
  )
  AND NOT EXISTS (
    SELECT 1 FROM "training_questions" AS existing
    WHERE existing."assessment_id" = a."id"
      AND existing."question_key" = 'venda_solucao_beneficio'
  );
--> statement-breakpoint
INSERT INTO "training_questions" ("assessment_id", "question_key", "type", "prompt", "config", "points", "position")
SELECT a."id", q.key, q.type, q.prompt, q.config::jsonb, q.points, q.position
FROM "training_assessments" AS a
JOIN "training_subjects" AS s ON s."id" = a."subject_id"
CROSS JOIN (VALUES
  ('venda_solucao_beneficio', 'multiple_choice', 'Segundo a regra central do POP, qual sequência transforma o atendimento em uma venda consultiva?', $question${"options":[{"id":"a","text":"Problema → solução/proposta de valor → benefício → evidência → preço.","correct":true,"feedback":"A sequência conecta a necessidade do cliente a um ganho e a fatos que sustentam a proposta."},{"id":"b","text":"Preço → lista de especificações → apresentação institucional → problema.","correct":false,"feedback":"Começar pelo preço e pelas especificações não diagnostica a necessidade nem demonstra valor."},{"id":"c","text":"Benefício genérico → promessa de resultado → preço menor que o concorrente.","correct":false,"feedback":"O benefício deve resolver a dor identificada e ser sustentado por evidência, sem promessas sem base."},{"id":"d","text":"Produto → superlativo → condição especial → fechamento imediato.","correct":false,"feedback":"O POP orienta descobrir o problema e justificar o valor com evidências."}],"explanation":"Vender é resolver o problema do cliente conectando solução, benefício e evidência objetiva antes de apresentar o preço."}$question$, 2, 90),
  ('pergunta_entrada_obrigatoria', 'multiple_choice', 'Qual é a pergunta de entrada obrigatória para iniciar a classificação do cliente?', $question${"options":[{"id":"a","text":"Hoje você fabrica letreiros ou terceiriza a produção?","correct":true,"feedback":"Essa pergunta identifica se o cliente fabrica, terceiriza ou está começando."},{"id":"b","text":"Você está começando e já quer investir em máquinas?","correct":false,"feedback":"Não é necessário perguntar separadamente se está começando; a resposta à pergunta de entrada revela o Grupo 1."},{"id":"c","text":"Seu fornecedor atual é ruim?","correct":false,"feedback":"Não pressuponha problema com o fornecedor; investigue a necessidade deste pedido."},{"id":"d","text":"Qual é o menor preço que você aceita?","correct":false,"feedback":"A conversa começa classificando e diagnosticando, antes de discutir preço."}],"explanation":"Se o cliente não fabrica nem terceiriza regularmente, a resposta já indica que está começando. Se faz ambos, classifique pelo motivo deste pedido."}$question$, 1, 95),
  ('classificacao_por_perfil', 'matching', 'Associe cada grupo à descrição correta do cliente.', $question${"leftItems":[{"id":"g1","text":"Grupo 1 — começando"},{"id":"g2","text":"Grupo 2 — fabrica"},{"id":"g3","text":"Grupo 3 — terceiriza"}],"rightItems":[{"id":"a","text":"Ainda não vende letras-caixa com recorrência ou terceiriza apenas ocasionalmente."},{"id":"b","text":"Produz internamente e pode precisar de um modelo que não fabrica ou de capacidade para um pedido."},{"id":"c","text":"Já compra de outro fornecedor e quer melhorar uma insatisfação específica."}],"correctPairs":[{"leftId":"g1","rightId":"a"},{"leftId":"g2","rightId":"b"},{"leftId":"g3","rightId":"c"}],"explanation":"A pergunta de entrada classifica a situação. Em perfis híbridos, o motivo deste pedido define o enquadramento."}$question$, 2, 100),
  ('oportunidade_grupo1', 'multiple_select', 'O cliente está começando e ainda não tem fábrica própria. Quais argumentos e ações são adequados ao Grupo 1?', $question${"allowPartialCredit":true,"options":[{"id":"sem_fabrica","text":"Mostrar que ele pode avaliar a venda de letras-caixa sem investir previamente em máquinas, equipe especializada e área produtiva própria.","correct":true,"feedback":"Conecta a oportunidade a uma necessidade concreta, sem garantir o resultado financeiro."},{"id":"portfolio","text":"Investigar os modelos que seus clientes pedem e confirmar quais opções do portfólio estão disponíveis.","correct":true,"feedback":"A pergunta de aprofundamento personaliza a oferta e a disponibilidade deve ser confirmada."},{"id":"crescimento","text":"Relacionar ampliação de portfólio e carteira a evidências institucionais validadas.","correct":true,"feedback":"O portfólio e os dados de clientes podem apoiar o argumento quando atuais e confirmados."},{"id":"lucro_garantido","text":"Garantir lucro, vendas ou liderança regional se ele começar a revender.","correct":false,"feedback":"O POP proíbe prometer lucro, vendas ou liderança como resultado garantido."},{"id":"beneficio_generico","text":"Apresentar todos os diferenciais antes de descobrir o que os clientes dele procuram.","correct":false,"feedback":"Primeiro investigue a carteira e a necessidade; escolha argumentos pertinentes."}],"explanation":"O Grupo 1 busca entrar no mercado, ampliar a oferta e se diferenciar. O vendedor apresenta uma oportunidade real sem garantir vendas ou lucro."}$question$, 2, 110),
  ('dois_motivos_grupo2', 'matching', 'Associe o motivo da terceirização de um fabricante ao benefício prioritário.', $question${"leftItems":[{"id":"nao_fabrica","text":"2A — não fabrica o modelo ou não domina o material/acabamento"},{"id":"sem_capacidade","text":"2B — equipe, máquinas ou calendário sem capacidade para o prazo"}],"rightItems":[{"id":"portfolio","text":"Ampliar o portfólio e aceitar projetos sem novo investimento produtivo."},{"id":"tempo","text":"Liberar tempo, absorver picos de demanda e reduzir a pressão operacional, após confirmar a capacidade e o prazo."},{"id":"culpar","text":"Dizer que a equipe do cliente é insuficiente e prometer qualquer prazo."}],"correctPairs":[{"leftId":"nao_fabrica","rightId":"portfolio"},{"leftId":"sem_capacidade","rightId":"tempo"}],"explanation":"O Grupo 2 exige separar falta de domínio de um modelo (2A) de sobrecarga/capacidade (2B); a solução e a evidência mudam conforme a causa."}$question$, 2, 120),
  ('escopo_pronto_para_instalar', 'best_response', 'O cliente pergunta se o letreiro chegará pronto para instalar. O pedido ainda não teve os itens de instalação conferidos. Qual resposta respeita o POP?', $question${"options":[{"id":"a","text":"Sim, todos os letreiros chegam prontos para fixação; não precisa conferir o que está incluído.","correct":false,"feedback":"A expressão só pode ser usada quando todos os componentes necessários estão incluídos na opção contratada."},{"id":"b","text":"Vou confirmar o escopo deste pedido e quais componentes estão incluídos antes de dizer se ele fica pronto para instalar.","correct":true,"feedback":"Apresenta o escopo real e verifica os itens antes de prometer conveniência ou instalação."},{"id":"c","text":"A embalagem e a conferência garantem que nenhum item faltará.","correct":false,"feedback":"Não transforme controles em garantia absoluta de resultado."}],"explanation":"Conferência, embalagem e modalidade de fornecimento devem corresponder ao pedido. Não afirme que toda opção está pronta para fixação."}$question$, 1, 130),
  ('diagnostico_grupo3', 'matching', 'Associe cada motivo do cliente que já terceiriza à pergunta de diagnóstico adequada.', $question${"leftItems":[{"id":"prazo","text":"Prazo"},{"id":"acabamento","text":"Acabamento"},{"id":"atendimento","text":"Atendimento"},{"id":"preco","text":"Preço"}],"rightItems":[{"id":"p","text":"Qual é sua data-limite real? O problema ocorre com todos os modelos ou neste pedido?"},{"id":"a","text":"Que defeito ocorreu, em qual material e qual foi o impacto para seu cliente?"},{"id":"t","text":"O que faltou: resposta, atualização, clareza ou solução do problema?"},{"id":"v","text":"Qual é a faixa de investimento e quais características são indispensáveis?"}],"correctPairs":[{"leftId":"prazo","rightId":"p"},{"leftId":"acabamento","rightId":"a"},{"leftId":"atendimento","rightId":"t"},{"leftId":"preco","rightId":"v"}],"explanation":"Não presuma que o fornecedor atual é ruim. Descubra a insatisfação específica, registre uma prioridade e, se houver, uma necessidade secundária."}$question$, 2, 140),
  ('objecao_acabamento', 'best_response', 'Um cliente relata um problema de acabamento em uma peça de determinado material. Qual é a melhor primeira resposta?', $question${"options":[{"id":"a","text":"Dizer que nunca há defeitos porque a empresa faz conferência em todas as peças.","correct":false,"feedback":"O POP não autoriza prometer zero retrabalho nem perfeição."},{"id":"b","text":"Acolher o relato, perguntar qual defeito ocorreu, em qual material e qual foi o impacto; depois mostrar controles vigentes ou exemplos reais pertinentes.","correct":true,"feedback":"Investiga a causa antes de escolher a evidência e evita uma alegação genérica."},{"id":"c","text":"Elogiar o cliente e enviar fotos de qualquer produto, mesmo sem relação com a necessidade.","correct":false,"feedback":"Elogios devem ser específicos e evidências precisam ser relevantes ao material e ao problema."}],"explanation":"Para acabamento, descubra o defeito, o material e o impacto; conecte a resposta a exemplos concretos e às etapas de conferência se estiverem vigentes."}$question$, 2, 150),
  ('objecao_atendimento', 'best_response', 'O cliente diz que seu fornecedor atual demora para atualizar o andamento do pedido. Como responder?', $question${"options":[{"id":"a","text":"Prometer atendimento 24 horas e disponibilidade pessoal aos fins de semana.","correct":false,"feedback":"O POP não transforma disponibilidade fora do expediente em promessa institucional."},{"id":"b","text":"Perguntar que informação ou atualização faltou e combinar comunicação clara, registro das decisões e um retorno no prazo acordado.","correct":true,"feedback":"Investiga a falha e demonstra acompanhamento sem prometer disponibilidade não formalizada."},{"id":"c","text":"Dizer que todos os concorrentes atendem mal e que isso nunca acontecerá aqui.","correct":false,"feedback":"Não ataque o fornecedor atual nem faça garantias sem base."}],"explanation":"Atendimento consultivo exige entender a falha concreta e combinar um próximo retorno que possa ser cumprido."}$question$, 2, 160),
  ('uso_responsavel_evidencias', 'multiple_select', 'Quais práticas respeitam as regras de uso das evidências institucionais do POP?', $question${"allowPartialCredit":true,"options":[{"id":"clientes","text":"Validar com a direção/CRM a atualização e o significado do dado de mais de 5 mil clientes antes de usá-lo externamente.","correct":true,"feedback":"A definição e a atualidade do dado precisam ser confirmadas."},{"id":"volume","text":"Usar a referência de mais de 400 letreiros por mês com período real e sem tratá-la como garantia de encaixe imediato.","correct":true,"feedback":"Volume demonstra escala, não disponibilidade para qualquer data."},{"id":"etapas","text":"Descrever as oito etapas de conferência somente se o checklist correspondente estiver vigente.","correct":true,"feedback":"A evidência precisa refletir o processo atual e documentado."},{"id":"equipe","text":"Atualizar a informação sobre dezenas de colaboradores e não confundir o total da empresa com a equipe produtiva.","correct":true,"feedback":"Use a medida correta e atualizada."},{"id":"portfolio","text":"Confirmar os materiais, acabamentos e produtos atualmente disponíveis antes de apresentá-los como opção.","correct":true,"feedback":"O portfólio deve corresponder à disponibilidade real."},{"id":"alternativas","text":"Oferecer alternativas de configuração apenas quando aprovadas e compatíveis com engenharia, segurança e escopo.","correct":true,"feedback":"A adequação de preço não pode ignorar validações técnicas."},{"id":"garantia","text":"Usar volume e carteira para garantir qualidade perfeita ou prazo em qualquer situação.","correct":false,"feedback":"Esses números demonstram experiência e escala, não garantem desempenho individual ou prazo."},{"id":"auditoria","text":"Apresentar os dados como garantias contratuais sem validar atualização ou definição.","correct":false,"feedback":"Os dados devem ser validados antes de uso público ou como promessa."}],"explanation":"Os números e processos foram informados pela direção e requerem validação. Evidências devem ser atuais, verificáveis e adequadas à necessidade."}$question$, 3, 170),
  ('referencias_prazo', 'multiple_choice', 'Como apresentar os prazos citados para alguns projetos no POP?', $question${"options":[{"id":"a","text":"Cerca de 4 dias úteis para determinados projetos em PVC e 10 a 11 dias úteis para letreiros acabados são referências; é preciso confirmar o prazo do modelo e a capacidade produtiva.","correct":true,"feedback":"São referências comerciais condicionais, não prazos gerais nem compromissos sem confirmação."},{"id":"b","text":"Todo projeto em PVC deve ser prometido em 4 dias úteis e todo letreiro acabado em 10 dias.","correct":false,"feedback":"Os prazos não são regra geral e dependem do produto e da capacidade."},{"id":"c","text":"A produção mensal acima de 400 peças garante encaixe imediato para qualquer pedido.","correct":false,"feedback":"Volume não garante capacidade disponível para a data solicitada."}],"explanation":"Consulte prazo e capacidade do produto. Só confirme uma data depois de verificar a situação real com a produção."}$question$, 2, 180),
  ('fala_consultiva', 'best_response', 'Qual fala segue a fórmula consultiva obrigatória do POP?', $question${"options":[{"id":"a","text":"Você me disse que precisa atender um prazo apertado. Por isso, neste pedido o mais importante é confirmar uma entrega viável. Posso verificar o prazo real deste modelo com a produção e te retorno com a data confirmada. Para avançarmos, qual é sua data-limite?","correct":true,"feedback":"Retoma a necessidade, relaciona o benefício, identifica uma evidência verificável e propõe uma próxima ação."},{"id":"b","text":"Temos muitos diferenciais e somos os melhores; vou mandar todo o portfólio e depois vemos o preço.","correct":false,"feedback":"É genérica, não diagnostica nem sustenta alegações com evidências."},{"id":"c","text":"Se fechar hoje, garanto entrega rápida e o melhor preço.","correct":false,"feedback":"Cria urgência e promete condições sem validação."}],"explanation":"A fala deve relacionar a necessidade nas palavras do cliente ao benefício, a um fato verificável e a uma pergunta ou próximo passo."}$question$, 2, 190),
  ('etapas_argumentacao', 'ordering', 'Ordene as cinco etapas da construção da argumentação consultiva.', $question${"steps":[{"id":"escutar","text":"Escutar: deixar o cliente explicar a situação."},{"id":"diagnosticar","text":"Diagnosticar: identificar a causa principal e, se houver, a secundária."},{"id":"personalizar","text":"Personalizar: escolher um ou dois benefícios pertinentes."},{"id":"demonstrar","text":"Demonstrar: apresentar evidência concreta, atual e relevante."},{"id":"avancar","text":"Avançar: confirmar interesse, prazo, especificação, investimento e próximo passo."}],"correctOrder":["escutar","diagnosticar","personalizar","demonstrar","avancar"],"explanation":"A apresentação da empresa e dos benefícios não deve antecipar a escuta e o diagnóstico."}$question$, 2, 200),
  ('tres_confiancas', 'matching', 'Associe o ponto de confiança que pode travar a compra a uma forma adequada de fortalecê-lo.', $question${"leftItems":[{"id":"produto","text":"Confiança no produto"},{"id":"empresa","text":"Confiança na empresa"},{"id":"vendedor","text":"Confiança no vendedor"}],"rightItems":[{"id":"p","text":"Fotos reais, especificações claras, escopo e acabamento do modelo."},{"id":"e","text":"Processo e estrutura, canais oficiais, referências e números institucionais validados."},{"id":"v","text":"Escuta, informações corretas, retorno combinado e transparência sobre limites."}],"correctPairs":[{"leftId":"produto","rightId":"p"},{"leftId":"empresa","rightId":"e"},{"leftId":"vendedor","rightId":"v"}],"explanation":"A técnica dos Três 10s orienta verificar a confiança no produto, na empresa e no vendedor. Uma mesma negociação pode ter dúvidas diferentes em cada ponto."}$question$, 2, 210),
  ('perspectivas_comprador', 'matching', 'Associe cada perspectiva de decisão ao que tende a pesar para o comprador.', $question${"leftItems":[{"id":"financeiro","text":"Financeiro"},{"id":"tecnico","text":"Técnico"},{"id":"executivo","text":"Executivo"}],"rightItems":[{"id":"f","text":"Preço, margem, custos, fluxo de caixa e condições aprovadas."},{"id":"t","text":"Materiais, medidas, acabamento, fixação e conformidade do projeto."},{"id":"e","text":"Crescimento, portfólio, diferenciação, capacidade, tempo e reputação."}],"correctPairs":[{"leftId":"financeiro","rightId":"f"},{"leftId":"tecnico","rightId":"t"},{"leftId":"executivo","rightId":"e"}],"explanation":"Essas perspectivas são uma adaptação prática para a conversa, não personalidades fixas: a mesma pessoa pode considerar mais de uma."}$question$, 2, 220),
  ('crm_campos_completos', 'multiple_select', 'Quais informações devem constar no registro de qualificação antes de concluí-lo, conforme o POP?', $question${"allowPartialCredit":true,"options":[{"id":"perfil_motivo","text":"Perfil do cliente e motivo principal do pedido, classificando o híbrido pelo motivo deste projeto.","correct":true,"feedback":"Registre o grupo e a causa que explica a procura atual."},{"id":"criterio_confianca","text":"Critério predominante de decisão e ponto de confiança que precisa ser reforçado.","correct":true,"feedback":"Identifique a perspectiva financeira, técnica ou executiva e a dúvida sobre produto, empresa ou vendedor."},{"id":"voz_cliente","text":"Necessidade em palavras do cliente, sem exagerar nem apresentar interpretação como citação.","correct":true,"feedback":"Mantenha o registro curto e fiel à fala."},{"id":"proposta_e_prova","text":"Benefício apresentado e evidência concreta utilizada.","correct":true,"feedback":"Registre qual argumento e qual evidência foram usados."},{"id":"dados_pedido","text":"Modelo/material, prazo, especificações críticas e faixa de investimento quando informados.","correct":true,"feedback":"Os detalhes dependem do que o cliente informou."},{"id":"proximo_passo","text":"Próximo passo e responsável, por exemplo consulta técnica, amostra, confirmação de prazo ou cotação.","correct":true,"feedback":"O registro precisa permitir continuidade do atendimento."},{"id":"lucro","text":"Lucro e conversão garantidos estimados pelo vendedor sem cálculo.","correct":false,"feedback":"O POP não autoriza prometer lucro ou conversão."},{"id":"suposicao","text":"Necessidades inferidas e apresentadas como se fossem palavras do cliente.","correct":false,"feedback":"Não distorça o que o cliente declarou."}],"explanation":"O CRM deve ligar perfil, motivo, necessidade, critério de decisão, benefício, evidência e próximo passo. Dados técnicos e faixa de investimento entram quando informados."}$question$, 2, 230),
  ('dados_para_cotacao', 'multiple_select', 'Quais cuidados fazem parte do avanço correto para uma cotação de letras-caixa?', $question${"allowPartialCredit":true,"options":[{"id":"vetor","text":"Solicitar o desenho vetorial editável necessário ao cálculo de área, perímetro e nesting.","correct":true,"feedback":"O POP diz que JPEG/PNG não substitui o vetor exigido para esses cálculos."},{"id":"material_medida","text":"Confirmar o material e as medidas do projeto.","correct":true,"feedback":"São dados técnicos necessários à cotação."},{"id":"acabamento_luz","text":"Confirmar acabamento e iluminação.","correct":true,"feedback":"Essas especificações afetam o produto e o escopo."},{"id":"fixacao_fornecimento","text":"Confirmar fixação e modalidade de fornecimento.","correct":true,"feedback":"É preciso saber o que será incluído e como será fornecido."},{"id":"raster","text":"Aceitar imagem JPEG ou PNG como substituta do arquivo vetorial para calcular área, perímetro e nesting.","correct":false,"feedback":"O arquivo raster não substitui o vetor requerido."}],"explanation":"Antes de orçar, obtenha o vetor editável e os dados técnicos do escopo: material, medidas, acabamento, iluminação, fixação e modalidade de fornecimento."}$question$, 2, 240),
  ('limites_comerciais', 'multiple_select', 'Quais atitudes o vendedor deve evitar, segundo a seção de limites comerciais?', $question${"allowPartialCredit":true,"options":[{"id":"superlativo","text":"Dizer que a empresa é a melhor, nunca atrasa, não tem retrabalho ou tem o menor preço sem base objetiva.","correct":true,"feedback":"São alegações que exigem evidência; não devem ser usadas sem base."},{"id":"prazo","text":"Prometer prazo excepcional antes de confirmar com a produção.","correct":true,"feedback":"Confirme modelo e capacidade antes do compromisso."},{"id":"escopo","text":"Dizer que toda opção está pronta para instalar sem conferir itens incluídos.","correct":true,"feedback":"A afirmação depende do escopo contratado."},{"id":"reducao","text":"Reduzir material ou acabamento sem explicar impacto, aprovação técnica e registro do escopo.","correct":true,"feedback":"Toda mudança precisa de transparência, revisão técnica e reorçamento."},{"id":"concorrente","text":"Atacar o fornecedor atual em vez de descobrir o que o cliente deseja melhorar.","correct":true,"feedback":"O POP orienta investigar a insatisfação sem desqualificar o concorrente."},{"id":"plantao","text":"Prometer atendimento pessoal 24 horas ou aos fins de semana sem política formal.","correct":true,"feedback":"Disponibilidade fora do expediente não é promessa institucional."},{"id":"lista","text":"Recitar toda a lista de benefícios sem relacioná-la ao problema relatado.","correct":true,"feedback":"Escolha um ou dois benefícios ligados à necessidade."},{"id":"confirmar","text":"Confirmar um prazo possível com a produção antes de comunicá-lo ao cliente.","correct":false,"feedback":"Confirmar o prazo é o comportamento correto."}],"explanation":"A seção 13 limita promessas, mudanças de escopo e argumentos genéricos. O vendedor diagnostica, verifica fatos e explica qualquer alteração."}$question$, 3, 250),
  ('indicadores_closer', 'multiple_select', 'Quais indicadores o POP sugere para acompanhar e melhorar a qualificação comercial?', $question${"allowPartialCredit":true,"options":[{"id":"classificados","text":"Percentual de leads classificados.","correct":true,"feedback":"É um indicador sugerido."},{"id":"argumento_registrado","text":"Percentual de oportunidades com dor, benefício e evidência registrados.","correct":true,"feedback":"Verifica se a argumentação foi ligada a uma necessidade e sustentada."},{"id":"conversao","text":"Taxa de cotação e conversão por grupo de cliente.","correct":true,"feedback":"Permite analisar os resultados por perfil."},{"id":"troca","text":"Principais motivos para trocar de fornecedor.","correct":true,"feedback":"Mostra quais insatisfações aparecem com mais frequência."},{"id":"promessa","text":"Reclamações e retrabalhos relacionados a promessas comerciais.","correct":true,"feedback":"Ajuda a identificar problemas decorrentes de afirmações não alinhadas ao escopo."},{"id":"criterio","text":"Percentual de oportunidades com critério decisório e ponto de confiança registrados.","correct":true,"feedback":"Verifica a qualidade do diagnóstico de decisão."},{"id":"mensagens","text":"Quantidade de mensagens enviadas por vendedor, independentemente do resultado ou do registro.","correct":false,"feedback":"Esse indicador não aparece na lista sugerida pelo POP."}],"explanation":"Acompanhe classificação, registro de dor/benefício/evidência, cotação e conversão por grupo, motivos de troca, efeitos de promessas e registro do critério decisório e da confiança."}$question$, 2, 260),
  ('lideranca_treinamento', 'best_response', 'O que cabe à liderança comercial para manter o atendimento alinhado ao material?', $question${"options":[{"id":"a","text":"Treinar por simulações, auditar amostras de conversas e atualizar periodicamente prazos, evidências e disponibilidade de produtos.","correct":true,"feedback":"Essas são as responsabilidades de melhoria contínua descritas no POP."},{"id":"b","text":"Criar uma cadência obrigatória de follow-up e manter prazos comerciais fixos mesmo quando a capacidade mudar.","correct":false,"feedback":"O POP não define cadência e orienta atualizar prazos e capacidade."},{"id":"c","text":"Permitir que cada vendedor use números antigos sem validação para manter consistência da fala.","correct":false,"feedback":"Prazos, evidências e disponibilidade precisam ser atualizados."}],"explanation":"A liderança pratica por simulação, audita conversas e mantém informações comerciais atualizadas."}$question$, 1, 270),
  ('mapa_necessidade_evidencia', 'matching', 'Associe a necessidade do cliente à evidência ou ação mais pertinente antes de apresentar o benefício.', $question${"leftItems":[{"id":"grupo1","text":"Grupo 1 quer ampliar a oferta sem montar fábrica."},{"id":"grupo2","text":"Grupo 2 está sobrecarregado e precisa cumprir um prazo."},{"id":"acabamento","text":"Grupo 3 relata um defeito de acabamento."},{"id":"prazo","text":"Grupo 3 precisa de uma data-limite realista."},{"id":"preco","text":"Grupo 3 precisa adequar o investimento sem abrir mão dos requisitos essenciais."}],"rightItems":[{"id":"portfolio","text":"Confirmar os modelos e materiais realmente disponíveis e investigar o que a carteira do cliente pede."},{"id":"capacidade","text":"Consultar prazo e capacidade deste modelo; usar escala e conferências somente como evidências atuais e documentadas."},{"id":"qualidade","text":"Identificar o defeito e o material, então mostrar exemplo ou controle de qualidade pertinente."},{"id":"data","text":"Confirmar prazo do modelo e capacidade produtiva antes de assumir uma data."},{"id":"escopo","text":"Perguntar faixa e requisitos inegociáveis; validar tecnicamente uma alternativa e reorçar com diferenças explícitas."}],"correctPairs":[{"leftId":"grupo1","rightId":"portfolio"},{"leftId":"grupo2","rightId":"capacidade"},{"leftId":"acabamento","rightId":"qualidade"},{"leftId":"prazo","rightId":"data"},{"leftId":"preco","rightId":"escopo"}],"explanation":"O mesmo argumento não serve para todos. Classifique, diagnostique e selecione a evidência relacionada à necessidade deste pedido."}$question$, 3, 280)
) AS q(key, type, prompt, config, points, position)
WHERE s."slug" = 'closer'
  AND a."id" = (
    SELECT min(initial."id")
    FROM "training_assessments" AS initial
    WHERE initial."subject_id" = s."id"
  )
  AND NOT EXISTS (
    SELECT 1 FROM "training_questions" AS existing
    WHERE existing."assessment_id" = a."id"
      AND existing."question_key" = q.key
  );
